import 'package:dio/dio.dart';

class ApiClient {
  late final Dio dio;

  ApiClient() {
    dio = Dio(BaseOptions(
      baseUrl: 'https://api.example.com',
      connectTimeout: const Duration(seconds: 5),
      receiveTimeout: const Duration(seconds: 10),
    ));

    dio.interceptors.add(AuthInterceptor(dio));
    dio.interceptors.add(LoggingInterceptor());
    dio.interceptors.add(ErrorInterceptor());
  }
}

// ── Auth interceptor ───────────────────────
class AuthInterceptor extends Interceptor {
  AuthInterceptor(this._dio);
  final Dio _dio;

  @override
  void onRequest(
    RequestOptions options,
    RequestInterceptorHandler handler,
  ) async {
    // Add token to all requests
    final token = await getAuthToken();
    if (token != null) {
      options.headers['Authorization'] = 'Bearer $token';
    }

    // Continue with modified request
    handler.next(options);
  }

  @override
  void onError(
    DioException err,
    ErrorInterceptorHandler handler,
  ) async {
    // Refresh token on 401 — but only once per request
    final opts = err.requestOptions;
    if (err.response?.statusCode == 401 && opts.extra['retried'] != true) {
      try {
        await refreshToken();          // de-duplicated: one in-flight refresh for all callers
        opts.extra['retried'] = true;  // stops an invalid token from looping forever
        opts.headers['Authorization'] = 'Bearer ${await getAuthToken()}';
        return handler.resolve(await _dio.fetch(opts)); // same base options + interceptors
      } catch (e) {
        return handler.reject(err);
      }
    }

    handler.next(err);
  }
}

// ── Logging interceptor ────────────────────
class LoggingInterceptor extends Interceptor {
  @override
  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
    print('REQUEST[${options.method}] => ${options.path}');
    print('Headers: ${options.headers}');
    print('Data: ${options.data}');
    handler.next(options);
  }

  @override
  void onResponse(Response response, ResponseInterceptorHandler handler) {
    print('RESPONSE[${response.statusCode}] => ${response.requestOptions.path}');
    print('Data: ${response.data}');
    handler.next(response);
  }

  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    print('ERROR[${err.response?.statusCode}] => ${err.requestOptions.path}');
    print('Message: ${err.message}');
    handler.next(err);
  }
}

