Future<File> downloadWithResume(String url, String finalPath) async {
  final part = File('$finalPath.part');
  final already = await part.exists() ? await part.length() : 0;

  final res = await dio.get<ResponseBody>(
    url,
    options: Options(
      responseType: ResponseType.stream,
      followRedirects: true,
      headers: already > 0 ? {'Range': 'bytes=$already-'} : null,
      validateStatus: (s) => s == 200 || s == 206,
    ),
  );

  // 200 means the server ignored our Range header: restart from zero
  final resumed = res.statusCode == 206;
  if (!resumed && already > 0) await part.delete();

  final totalHeader = res.headers.value('content-length');
  final total = (int.tryParse(totalHeader ?? '') ?? 0) + (resumed ? already : 0);
  var received = resumed ? already : 0;

  final sink = part.openWrite(mode: resumed ? FileMode.append : FileMode.write);
  try {
    await for (final chunk in res.data!.stream) {
      sink.add(chunk);
      received += chunk.length;
      progress.value = total > 0 ? received / total : null; // null -> indeterminate
    }
  } finally {
    await sink.close();
  }

  if (total > 0 && received != total) {
    throw StateError('truncated download: $received of $total');
  }
  return part.rename(finalPath);   // ✅ atomic-ish: no half file at finalPath
}

