class RetryInterceptor extends Interceptor {
  RetryInterceptor(this._dio, {this.maxAttempts = 3});

  final Dio _dio;
  final int maxAttempts;
  final _rand = Random();

  static const _transientStatus = {408, 429, 502, 503, 504};
  static const _idempotent = {'GET', 'HEAD', 'PUT', 'DELETE'};

  @override
  Future<void> onError(DioException err, ErrorInterceptorHandler h) async {
    final o = err.requestOptions;
    final attempt = (o.extra['attempt'] as int? ?? 0) + 1;
    // A POST is replayable only behind a key the backend deduplicates on
    final safe = _idempotent.contains(o.method.toUpperCase()) ||
        o.headers.containsKey('Idempotency-Key');

    if (!safe || attempt > maxAttempts || !_transient(err)) {
      return h.next(err);
    }

    o.extra['attempt'] = attempt;                 // travels with the retry
    await Future<void>.delayed(_serverDelay(err) ?? _backoff(attempt));
    try {
      h.resolve(await _dio.fetch(o));
    } on DioException catch (e) {
      h.next(e);
    }
  }

  bool _transient(DioException e) =>
      !CancelToken.isCancel(e) &&
      (e.type == DioExceptionType.connectionError ||
          e.type == DioExceptionType.connectionTimeout ||
          e.type == DioExceptionType.receiveTimeout ||
          _transientStatus.contains(e.response?.statusCode));

  Duration _backoff(int attempt) {
    final ms = min(500 * pow(2, attempt - 1).toInt(), 8000);
    return Duration(milliseconds: ms + _rand.nextInt(250)); // jitter
  }

  Duration? _serverDelay(DioException e) {
    final seconds = int.tryParse(e.response?.headers.value('retry-after') ?? '');
    return seconds == null ? null : Duration(seconds: seconds);
  }
}

