class AuthInterceptor extends Interceptor {
  AuthInterceptor(this._dio, this._store);

  final Dio _dio;                 // the app client, used to replay
  final TokenStore _store;
  final Dio _plain = Dio(BaseOptions(baseUrl: 'https://api.example.com'));
  Future<String>? _refreshing;    // the single flight

  @override
  void onRequest(RequestOptions o, RequestInterceptorHandler h) {
    o.headers['Authorization'] = 'Bearer ${_store.access}';
    h.next(o);
  }

  @override
  Future<void> onError(DioException err, ErrorInterceptorHandler h) async {
    final o = err.requestOptions;
    if (err.response?.statusCode != 401 || o.extra['retried'] == true) {
      return h.next(err);
    }

    final sent = o.headers['Authorization'] as String?;
    try {
      // ✅ one refresh serves every waiting request
      final fresh = sent == 'Bearer ${_store.access}'
          ? await (_refreshing ??= _refresh())
          : _store.access!;              // someone refreshed while we queued

      o.extra['retried'] = true;
      o.headers['Authorization'] = 'Bearer $fresh'; // header at replay time
      h.resolve(await _dio.fetch(o));
    } on DioException catch (e) {
      if (e.response != null) _store.signOut(); // 4xx on refresh = real logout
      h.next(err);                              // a network error is not
    }
  }

  Future<String> _refresh() async {
    try {
      final res = await _plain.post('/auth/refresh',
          data: {'refresh_token': _store.refresh});
      await _store.save(res.data['access'], res.data['refresh']); // persist first
      return _store.access!;
    } finally {
      _refreshing = null; // let the next expiry start a new flight
    }
  }
}

