// ✅ bounded fan-out that keeps a per-item outcome
typedef Outcome = ({String id, Detail? value, Object? error});

Future<List<Outcome>> loadAll(
  List<String> ids, {
  int concurrency = 6,
  CancelToken? cancel,
}) async {
  final queue = List.of(ids);
  final out = <Outcome>[];

  Future<void> worker() async {
    while (queue.isNotEmpty && !(cancel?.isCancelled ?? false)) {
      final id = queue.removeAt(0);
      try {
        out.add((id: id, value: await api.detail(id, cancel: cancel), error: null));
      } catch (e) {
        out.add((id: id, value: null, error: e)); // a failed item, not a screen
      }
    }
  }

  await Future.wait([
    for (var i = 0; i < min(concurrency, ids.length); i++) worker(),
  ]);
  return out;
}

