class SseEvent {
  const SseEvent(this.event, this.data, this.id);
  final String event;
  final String data;
  final String? id;
}

Stream<SseEvent> sse(Dio dio, String path,
    {String? lastId, CancelToken? cancel}) async* {
  final res = await dio.get<ResponseBody>(
    path,
    cancelToken: cancel,
    options: Options(
      responseType: ResponseType.stream,
      receiveTimeout: Duration.zero, // ✅ no per-chunk clock on a long stream
      headers: {
        'Accept': 'text/event-stream',
        'Cache-Control': 'no-cache',
        if (lastId != null) 'Last-Event-ID': lastId, // resume where we stopped
      },
    ),
  );

  var event = 'message';
  var id = lastId;
  final data = StringBuffer();

  // ❌ one chunk is not one event:
  //    await for (final c in res.data!.stream) handle(utf8.decode(c));
  final lines = res.data!.stream
      .cast<List<int>>()
      .transform(utf8.decoder)      // ✅ survives a char split across chunks
      .transform(const LineSplitter());

  await for (final line in lines) {
    if (line.isEmpty) {                       // blank line dispatches
      if (data.isNotEmpty) yield SseEvent(event, data.toString(), id);
      event = 'message';
      data.clear();
    } else if (line.startsWith(':')) {
      continue;                               // heartbeat comment
    } else if (line.startsWith('data:')) {
      if (data.isNotEmpty) data.write('\n');  // multi-line data joins
      data.write(line.substring(5).trimLeft());
    } else if (line.startsWith('event:')) {
      event = line.substring(6).trim();
    } else if (line.startsWith('id:')) {
      id = line.substring(3).trim();          // feeds Last-Event-ID on reconnect
    }
  }
}
